{"implementation":"def solve(case):
    payload = case['payload']
    segments = payload['segments']
    budget = payload['budget']

    # Validate fields
    for seg in segments:
        if not all(k in seg for k in ('name','importance','minimum','capacity')):
            raise ValueError('Missing segment field')
    if not isinstance(budget, int):
        raise ValueError('Budget must be integer')

    total_min = sum(seg['minimum'] for seg in segments)
    total_cap = sum(seg['capacity'] for seg in segments)
    if budget < total_min or budget > total_cap:
        raise ValueError('Budget out of range')

    # Initialize allocations at minimum
    allocations = {seg['name']: seg['minimum'] for seg in segments}
    remaining = budget - total_min

    # Order of segments for tie-breaking
    order = [seg['name'] for seg in segments]

    while remaining > 0:
        best_score = -1.0
        best_idx = -1
        for i, name in enumerate(order):
            seg = next(s for s in segments if s['name'] == name)
            cur = allocations[name]
            if cur >= seg['capacity']:
                continue
            score = seg['importance'] / (cur + 1)
            if score > best_score:
                best_score = score
                best_idx = i
        if best_idx == -1:
            break
        best_name = order[best_idx]
        allocations[best_name] += 1
        remaining -= 1

    # Build result
    result = {
        'allocations': allocations,
        'names': order,
        'total': budget
    }
    return result"}
